/* main.min.js - versão minificada fornecida para produção */
/* Funcionalidades: toggle nav, toggles de contraste e dark mode, melhorias de teclado */
(function(){var d=document;function by(id){return d.getElementById(id)}
// nav toggles
var navToggles=[by('nav-toggle'),by('nav-toggle-2'),by('nav-toggle-3'),by('nav-toggle-4')];
navToggles.forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){var attr=this.getAttribute('aria-controls');var nav=attr?document.getElementById(attr):null;var expanded=this.getAttribute('aria-expanded')==='true';this.setAttribute('aria-expanded',!expanded);if(nav){nav.style.display=!expanded?'block':'none'}},false)});
// accessibility toggles
var tc=by('toggle-contrast'), td=by('toggle-dark');
tc&&tc.addEventListener('click',function(){document.documentElement.classList.toggle('high-contrast')});
td&&td.addEventListener('click',function(){document.documentElement.classList.toggle('dark-mode')});
// basic form accessible submit (no server) - client validation
var form=by('contact-form');form&&form.addEventListener('submit',function(e){if(!form.checkValidity()){e.preventDefault();form.querySelector(':invalid').focus()}},false);
// keyboard shortcut: press "0" to focus skip link (example of keyboard affordance)
d.addEventListener('keydown',function(e){if(e.key==='0'){var s=d.querySelector('.skip-link');s&&s.focus()}},false);
})();